"use strict";var Logout=function(n){var t={initialize:function(){t.initEvent()},initEvent:function(){n("#btnLogout").on("click",function(){t.handleShowFeedback()});n("#btnLogoutMobile").on("click",function(){t.handleShowFeedback()})},handleShowFeedback:function(){n.ajax({url:Site.resolveRelativeLangUrl("UserPanel/Feedback/Index?isClickLogout=true"),type:"GET",dataType:"html",cache:!1,success:function(t){n("#groupAuth").append('<div id="affFeedback">'+t+"<\/div>")},complete:function(){n("#affFeedbackContainer").length||(n("#affFeedback").remove(),window.location.href=Site.resolveRelativeLangUrl("Auth/SignOut"))}})}};return t}(jQuery);Logout.initialize();